def deprecated(message):
    """Decorator for deprecating functions and methods.

    :param message: Deprecation message to display when the function is called.
    :type message: str
    """
    if not isinstance(message, str):
        raise TypeError(f"message must be a string, got {type(message).__name__}")
    def decorator(func):
        if not callable(func):
            raise TypeError(f"decorated object must be callable, got {type(func).__name__}")
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        # Append a deprecation notice to the docstring
        existing_doc = func.__doc__ or ""
        wrapper.__doc__ = existing_doc + ("\n\n" if existing_doc else "") + f"*Deprecated*: {message}"
        return wrapper
    return decorator<|return|>

