def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # Ensure output is a list
    if output is None:
        output = []
    elif not isinstance(output, list):
        raise TypeError("output must be a list or None")

    # Reject None as a valid sequence
    if sequence is None:
        raise ValueError("sequence cannot be None")

    # Treat strings and bytes as single interfaces
    if isinstance(sequence, (str, bytes)):
        output.append(sequence)
        return output

    # Handle special case for Broken base classes
    try:
        if Broken in getattr(sequence, "__bases__", ()):
            return [sequence]
    except NameError:
        # Broken not defined; ignore
        pass

    # Determine if the object is an interface or implements spec
    cls = sequence.__class__
    try:
        if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
            output.append(sequence)
            return output
    except NameError:
        # InterfaceClass or Implements not defined; ignore
        pass

    # If the sequence is iterable, recurse into its elements
    try:
        for item in sequence:
            _normalizeargs(item, output)
    except TypeError:
        # Not iterable; treat as a single interface
        output.append(sequence)

    return output<|return|>

