def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate that the application has the expected structure
    try:
        spec = getattr(app, "spec", None)
        if spec is None:
            raise AttributeError("Application has no 'spec' attribute")
        manifest = getattr(spec, "manifest", None)
        if manifest is None:
            raise AttributeError("Spec has no 'manifest' attribute")
        # Ensure observer_schema is a dict; create if missing
        observer_schema = getattr(spec, "observer_schema", None)
        if observer_schema is None:
            observer_schema = {}
            setattr(spec, "observer_schema", observer_schema)
        if not isinstance(observer_schema, dict):
            raise TypeError("spec.observer_schema must be a dict")
    except Exception as exc:
        raise ValueError(f"Invalid application structure: {exc}") from exc

    # Normalize manifest to an iterable of resources
    if isinstance(manifest, dict):
        resources = manifest.values()
    elif isinstance(manifest, (list, tuple)):
        resources = manifest
    else:
        raise TypeError("spec.manifest must be a list or dict of resources")

    for resource in resources:
        if not isinstance(resource, dict):
            # Skip non-dict entries
            continue
        metadata = resource.get("metadata", {})
        name = metadata.get("name")
        kind = resource.get("kind")
        if not name or not kind:
            # Skip resources without a name or kind
            continue
        # Skip if a custom observer schema already exists for this resource
        if name in observer_schema:
            continue
        # Build a minimal default observer schema
        default_schema = {
            "apiVersion": resource.get("apiVersion", ""),
            "kind": kind,
            "metadata": {
                "name": name,
                "namespace": metadata.get("namespace", ""),
            },
        }
        observer_schema[name] = default_schema
    # No explicit return value; the function mutates app.spec.observer_schema in place.<|return|>

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False

        # If path is a pyfilesystem root (has getinfo), try to use it
        if hasattr(path, "getinfo"):
            try:
                # Check for the presence of the OCFL manifest file
                info = path.getinfo(".ocfl/manifest")
                if not getattr(info, "is_file", False):
                    return False
                return True
            except Exception:
                return False

        # Treat path as a normal filesystem path
        import os
        if not os.path.isdir(path):
            return False

        manifest_path = os.path.join(path, ".ocfl", "manifest")
        if not os.path.isfile(manifest_path):
            return False

        return True
    except Exception:
        return False<|return|>

