def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate inputs
    if manifest_files is None:
        raise ValueError("manifest_files must be provided")
    if digests_used is None:
        raise ValueError("digests_used must be provided")

    # Ensure digests_used is a set for efficient lookup
    try:
        digests_used_set = set(digests_used)
    except TypeError:
        raise ValueError("digests_used must be an iterable of digests")

    # Collect digests from manifest
    manifest_digests = set()
    for item in manifest_files:
        # Support dicts with 'digest' key
        if isinstance(item, dict):
            digest = item.get('digest')
        else:
            digest = getattr(item, 'digest', None)
        if digest:
            manifest_digests.add(digest)

    # Digests that are in the manifest but not used
    missing = manifest_digests - digests_used_set
    if missing:
        raise ValueError(f"Digests from manifest not used: {sorted(missing)}")

    # Optionally, check for digests that are used but not present in the manifest
    unused = digests_used_set - manifest_digests
    if unused:
        raise ValueError(f"Digests used but not present in manifest: {sorted(unused)}")

    return True<|return|>

