def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory cannot be None")
    if version is None:
        raise ValueError("version cannot be None")

    result = {}

    # Handle inventory as a dict mapping logical_path -> versioned data
    if isinstance(inventory, dict):
        for logical_path, data in inventory.items():
            if isinstance(data, dict):
                # data is a mapping of version -> iterable of content files
                files = set()
                for ver, content_set in data.items():
                    if ver == version:
                        try:
                            files.update(content_set)
                        except TypeError:
                            # content_set is not iterable, treat as single file
                            files.add(content_set)
                if files:
                    result[logical_path] = files
            else:
                # data is an iterable of (ver, content_file) tuples
                files = set()
                for entry in data:
                    if isinstance(entry, (list, tuple)) and len(entry) == 2:
                        ver, content_file = entry
                        if ver == version:
                            files.add(content_file)
                if files:
                    result[logical_path] = files

    # Handle inventory as a list/tuple of entries
    elif isinstance(inventory, (list, tuple)):
        for entry in inventory:
            if isinstance(entry, dict):
                lp = entry.get("logical_path")
                cf = entry.get("content_file")
                ver = entry.get("version")
                if lp is not None and cf is not None and ver == version:
                    result.setdefault(lp, set()).add(cf)
            elif isinstance(entry, (list, tuple)) and len(entry) == 3:
                lp, cf, ver = entry
                if ver == version:
                    result.setdefault(lp, set()).add(cf)

    else:
        raise TypeError("Unsupported inventory type: %s" % type(inventory).__name__)

    return result<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if 'files' not in fixity:
        raise ValueError("Fixity block missing required 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' entry must be a list")

    # Ensure manifest_files is iterable
    try:
        manifest_set = set(manifest_files or [])
    except TypeError:
        raise ValueError("manifest_files must be an iterable of file paths")

    # Define required keys for each file entry
    required_keys = {'path', 'hash', 'size'}

    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"File entry at index {idx} must be a dictionary")
        missing = required_keys - entry.keys()
        if missing:
            raise ValueError(
                f"File entry at index {idx} missing required keys: {', '.join(sorted(missing))}"
            )
        path = entry['path']
        if path not in manifest_set:
            raise ValueError(f"File '{path}' referenced in fixity block is not present in the manifest")

    # If all checks pass, return True for convenience
    return True<|return|>

def files_list(path):
    """
    Return the files in `path`.

    If `path` is a file, returns a list containing that file's absolute path.
    If `path` is a directory, returns a list of absolute paths of all files
    (non-directories) directly inside that directory. The list is sorted
    alphabetically. Raises FileNotFoundError if the path does not exist.
    """
    if path is None:
        raise TypeError("path must not be None")
    # Resolve to absolute path
    abs_path = os.path.abspath(path)
    if not os.path.exists(abs_path):
        raise FileNotFoundError(f"Path does not exist: {abs_path}")
    if os.path.isfile(abs_path):
        return [abs_path]
    if os.path.isdir(abs_path):
        try:
            entries = os.listdir(abs_path)
        except OSError as exc:
            raise OSError(f"Error listing directory {abs_path}") from exc
        files = []
        for entry in entries:
            full = os.path.join(abs_path, entry)
            if os.path.isfile(full):
                files.append(full)
        return sorted(files)
    # If path exists but is neither file nor directory (e.g., symlink to non-file)
    raise FileNotFoundError(f"Unsupported path type: {abs_path}")<|return|>

