def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Validate inputs
    if node is None:
        return None
    if not pubdate_xpaths:
        return None

    # Ensure we have an iterable of xpaths
    if isinstance(pubdate_xpaths, (str, bytes)):
        xpaths = [pubdate_xpaths]
    else:
        try:
            iter(pubdate_xpaths)
            xpaths = list(pubdate_xpaths)
        except TypeError:
            # Not iterable, treat as single xpath
            xpaths = [pubdate_xpaths]

    for xpath in xpaths:
        if not xpath:
            continue
        try:
            # Try XPath if supported
            if hasattr(node, "xpath"):
                matches = node.xpath(xpath)
            # Fallback to CSS selector for BeautifulSoup-like objects
            elif hasattr(node, "select"):
                matches = node.select(xpath)
            else:
                # Unsupported node type
                continue

            if matches:
                return matches[0]
        except Exception:
            # Ignore errors for this xpath and try the next one
            continue

    # No match found
    return None<|return|>

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    # Validate the hook argument
    if hook is None:
        raise TypeError("hook must not be None")
    try:
        hash(hook)
    except TypeError:
        raise TypeError("hook must be hashable")

    # Ensure the registry exists and is a dictionary
    if not hasattr(self, "_registry"):
        self._registry = {}
    if not isinstance(self._registry, dict):
        raise TypeError("self._registry must be a dict")

    # Ensure there is a list for this hook
    if hook not in self._registry:
        self._registry[hook] = []
    elif not isinstance(self._registry[hook], list):
        raise TypeError(f"registry entry for hook {hook!r} must be a list")

    def decorator(fn):
        if not callable(fn):
            raise TypeError("registered handler must be callable")
        self._registry[hook].append(fn)
        return fn

    return decorator<|return|>

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not callable(namefunc):
        raise TypeError('namefunc must be callable')
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if PY3:
            return result
        else:
            # Python 2: convert unicode to bytes
            try:
                if isinstance(result, unicode):
                    return result.encode()
            except NameError:
                # unicode not defined, fallback
                pass
            return result
    return wrapper<|return|>

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"

    # Attempt to read a VERSION file in the current directory
    try:
        with open("VERSION", "r", encoding="utf-8") as f:
            version = f.read().strip()
            if version:
                return version
    except Exception:
        pass

    # Attempt to import a module named 'version' and read __version__ or VERSION
    try:
        import importlib.util
        spec = importlib.util.find_spec("version")
        if spec is not None:
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            if hasattr(module, "__version__"):
                return str(module.__version__).strip()
            if hasattr(module, "VERSION"):
                return str(module.VERSION).strip()
    except Exception:
        pass

    # Attempt to use pkg_resources to get the distribution version
    try:
        import pkg_resources
        # Try to get the distribution that contains this module
        dist = pkg_resources.get_distribution(__name__)
        return dist.version
    except Exception:
        pass

    # If all attempts fail, return the default value
    return default<|return|>

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        if isinstance(pieces, str):
            return '.' if '+' in pieces else '+'
        elif isinstance(pieces, (list, tuple, set)):
            return '.' if any('+' in str(item) for item in pieces) else '+'
        else:
            return '+'
    except Exception:
        return '+'<|return|>

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate commands
    if commands is None:
        raise ValueError("commands must not be None")
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a string or a list/tuple of strings")
    if not commands:
        raise ValueError("commands list cannot be empty")

    # Validate args
    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of strings")
    for a in args:
        if not isinstance(a, str):
            raise TypeError("each argument must be a string")

    # Prepare environment
    if env is None:
        env = os.environ.copy()
    else:
        if not isinstance(env, dict):
            raise TypeError("env must be a dict or None")
        env = env.copy()

    outputs = []
    for cmd in commands:
        if not isinstance(cmd, str):
            raise TypeError("each command must be a string")
        full_cmd = [cmd] + list(args)

        if verbose:
            print("Running command:", " ".join(full_cmd))

        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else None,
                text=True,
                check=True,
            )
            outputs.append(result.stdout)
        except subprocess.CalledProcessError as e:
            # Re-raise with the same information
            raise subprocess.CalledProcessError(
                e.returncode, e.cmd, output=e.output, stderr=e.stderr
            ) from None

    return outputs<|return|>

