def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Ensure we have a storage root to work with
    storage_root = getattr(self, "_storage_root", None)
    if storage_root is None:
        if show_warnings:
            print("Warning: No storage root found; nothing to validate.")
        return 0, 0

    # Ensure the storage root is iterable
    try:
        iterator = iter(storage_root)
    except TypeError:
        raise TypeError(f"_storage_root must be an iterable, got {type(storage_root).__name__}")

    num_objects = 0
    good_objects = 0

    for obj_id, obj in storage_root.items():
        num_objects += 1
        is_good = True

        # Validate the object if requested
        if validate_objects:
            try:
                if hasattr(obj, "validate"):
                    result = obj.validate()
                    if result is False:
                        is_good = False
                else:
                    # If no validate method, assume it's valid
                    pass
            except Exception as exc:
                is_good = False
                if show_warnings:
                    print(f"Validation error for object {obj_id}: {exc}")

        # Check digest if requested
        if check_digests:
            try:
                if hasattr(obj, "check_digest"):
                    result = obj.check_digest()
                    if result is False:
                        is_good = False
                else:
                    # If no check_digest method, assume digest is valid
                    pass
            except Exception as exc:
                is_good = False
                if show_warnings:
                    print(f"Digest check error for object {obj_id}: {exc}")

        if is_good:
            good_objects += 1

    return num_objects, good_objects<|return|>

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    version = version.strip()
    if not version:
        return "0"
    parts = version.split('.')
    if any(part == '' for part in parts):
        raise ValueError("Invalid version format: empty component")
    # Validate numeric parts
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"Non-numeric component in version: {part}")
    # Increment the last component
    last = parts[-1]
    width = len(last)
    try:
        new_last = str(int(last) + 1)
    except ValueError:
        raise ValueError(f"Invalid numeric value: {last}")
    # Preserve zero padding if width > 1
    if width > 1:
        new_last = new_last.rjust(width, '0')
    parts[-1] = new_last
    return '.'.join(parts)<|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        raise ValueError("version_dirs cannot be empty")

    known_files = set()
    root_inventory = None
    differences = {}

    for idx, dir_name in enumerate(version_dirs):
        if not isinstance(dir_name, str):
            raise TypeError(f"directory name at position {idx} must be a string")

        inventory_path = os.path.join(dir_name, "inventory.json")
        if not os.path.isfile(inventory_path):
            raise FileNotFoundError(f"Inventory file not found: {inventory_path}")

        try:
            with open(inventory_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except Exception as e:
            raise ValueError(f"Failed to load inventory from {inventory_path}: {e}")

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory in {inventory_path} must be a mapping")

        if idx == 0:
            root_inventory = inv

        missing = known_files - inv.keys()
        if missing:
            raise ValueError(f"Inventory in {inventory_path} missing files: {missing}")

        for file_path, digest in inv.items():
            root_digest = root_inventory.get(file_path)
            if root_digest is not None and root_digest != digest:
                differences.setdefault(file_path, []).append(dir_name)

        known_files.update(inv.keys())

    self.different_digests = differences
    return self<|return|>

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Basic validation
    if not isinstance(path, str):
        return "invalid path: not a string"

    try:
        if not os.path.exists(path):
            return "path does not exist"

        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            try:
                entries = os.listdir(path)
            except OSError as exc:
                return f"cannot list directory: {exc}"

            # Find Namaste file(s) starting with '0='
            namaste_found = any(entry.startswith("0=") for entry in entries)
            if not namaste_found:
                return "no Namaste file found"

            # Check for inventory.json to distinguish object from root
            if "inventory.json" in entries:
                return "object"
            else:
                return "root"

        return "unknown path type"
    except Exception as exc:
        return f"error: {exc}"
<|return|>

def parse_arguments(*arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    """
    import argparse
    import sys

    # Flatten arguments if a single list/tuple is passed
    if len(arguments) == 1 and isinstance(arguments[0], (list, tuple)):
        args = list(arguments[0])
    else:
        args = list(arguments)

    parser = argparse.ArgumentParser(description='Parse command line arguments')
    try:
        if args:
            known, unknown = parser.parse_known_args(args)
        else:
            known, unknown = parser.parse_known_args()
    except Exception as exc:
        raise RuntimeError(f"Error parsing arguments: {exc}") from exc

    # Attach any unknown arguments for reference
    known.unknown = unknown
    return known<|return|>

def parser_flags(parser):
    """Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated string."""
    if parser is None:
        raise TypeError("parser cannot be None")
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    for action in parser._actions:
        # option_strings is a list of flag strings for optional arguments
        if hasattr(action, "option_strings"):
            flags.extend(action.option_strings)
    return " ".join(flags)<|return|>

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    # Create a base parser. The caller is expected to add subparsers to this parser
    # before calling this function. We only add the subparsers container here.
    parser = argparse.ArgumentParser()
    parser.add_subparsers(dest='subparser_name')

    try:
        # Use parse_known_args so that unknown arguments do not raise an error
        namespace, _ = parser.parse_known_args(list(unparsed_arguments))
    except Exception:
        # If parsing fails for any reason, return an empty mapping
        return {}

    result = {}
    sub_name = getattr(namespace, 'subparser_name', None)

    if sub_name:
        # Store the full namespace under the subparser name
        result[sub_name] = namespace
        # Build a separate namespace for global arguments (exclude the subparser name)
        global_ns = argparse.Namespace()
        for key, value in vars(namespace).items():
            if key != 'subparser_name':
                setattr(global_ns, key, value)
        result['global'] = global_ns
    else:
        # No subparser was used; all arguments are global
        result['global'] = namespace

    return result<|return|>

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Validate inputs
    if subparsers is None:
        subparsers = {}
    if not isinstance(subparsers, dict):
        raise TypeError(f'subparsers must be a dict, got {type(subparsers).__name__}')
    if unparsed_arguments is None:
        unparsed_arguments = []
    if not isinstance(unparsed_arguments, (list, tuple)):
        try:
            unparsed_arguments = list(unparsed_arguments)
        except Exception as exc:
            raise TypeError(f'unparsed_arguments must be a sequence, got {type(unparsed_arguments).__name__}') from exc

    parsed_results = {}
    all_parsed_args = set()

    for name, parser in subparsers.items():
        if not isinstance(name, str):
            raise TypeError(f'subparser name must be a string, got {type(name).__name__}')
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f'subparser for "{name}" must be an argparse.ArgumentParser instance')
        try:
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
        except Exception as exc:
            # If parsing fails, we still want to return what we have
            namespace = None
            remaining = list(unparsed_arguments)
        parsed_results[name] = namespace
        # Arguments that were consumed by this parser
        parsed_args_set = set(unparsed_arguments) - set(remaining)
        all_parsed_args.update(parsed_args_set)

    # Remaining arguments not claimed by any subparser
    remaining_not_claimed = [arg for arg in unparsed_arguments if arg not in all_parsed_args]

    return parsed_results, remaining_not_claimed<|return|>

def make_parsers():
    '''
    Build a top-level parser and its subparsers and return them as a tuple.
    '''
    try:
        parser = argparse.ArgumentParser(description='Top-level parser')
        subparsers = parser.add_subparsers(dest='command', help='Sub-commands')
        return parser, subparsers
    except Exception as exc:
        raise RuntimeError(f"Failed to create parsers: {exc}") from exc<|return|>

def parser_flags(parser):
    """Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string."""
    if parser is None or not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    for action in parser._actions:
        if action.option_strings:
            flags.extend(action.option_strings)
    return " ".join(flags)<|return|>

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    # Validate inputs
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping names to ArgumentParser instances")
    if unparsed_arguments is None:
        unparsed_arguments = []
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of strings")
    args_list = list(unparsed_arguments)

    parsed_map = {}
    claimed_set = set()

    for name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(args_list)
        except SystemExit:
            # Parsing failed (e.g., missing required arguments); treat as no claims
            namespace = type('Namespace', (), {})()
            remaining = args_list
        # Determine which arguments were recognized by this parser
        recognized = []
        remaining_copy = list(remaining)
        for arg in args_list:
            if arg in remaining_copy:
                remaining_copy.remove(arg)
            else:
                recognized.append(arg)
        # Update claimed set
        claimed_set.update(recognized)
        parsed_map[name] = namespace

    # Remaining arguments not claimed by any subparser
    remaining_args = [arg for arg in args_list if arg not in claimed_set]
    return parsed_map, remaining_args<|return|>

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types
    if response is None:
        raise TypeError("response must be a list, got None")
    if not isinstance(response, list):
        raise TypeError(f"response must be a list, got {type(response).__name__}")
    if not isinstance(max_results, int):
        raise TypeError(f"max_results must be an int, got {type(max_results).__name__}")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Yield pages
    for start in range(0, len(response), max_results):
        yield response[start:start + max_results]<|return|>

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for key {key!r} must be numeric, got {type(value).__name__}")
            result[key] = result.get(key, 0) + value
    return result<|return|>

def _replace_url_args(self, url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    # Ensure url_args is a mapping-like object
    if not isinstance(url_args, dict) and not hasattr(url_args, 'keys'):
        return url

    # Pattern to find placeholders like {key}
    pattern = r'\{([^}]+)\}'

    def _repl(match):
        key = match.group(1)
        if key in url_args:
            value = url_args[key]
            # Convert to string and URL-encode
            try:
                import urllib.parse
                return urllib.parse.quote(str(value), safe='')
            except Exception:
                return str(value)
        return match.group(0)

    try:
        import re
        return re.sub(pattern, _repl, url)
    except Exception:
        # Fallback: return original url if regex fails
        return url<|return|>

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if val is None:
        return True
    if isinstance(val, str):
        stripped = val.strip()
        if not stripped:
            return True
        if stripped.lower() in ('none', 'null', 'nan'):
            return True
    return False<|return|>

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two characters to represent a base")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        pad_len = padding - len(result)
        result = alphabet[0] * pad_len + result

    return result<|return|>

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Validate input types
    if not isinstance(flow_params, (dict, list)):
        raise TypeError("flow_params must be a dict or list of dicts")
    if not isinstance(register_number, int):
        raise TypeError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string")

    # Determine iterable of flow dictionaries
    if isinstance(flow_params, dict):
        flows = flow_params.values()
    else:
        flows = flow_params

    # Replace the value for the specified key in each flow
    for flow in flows:
        if isinstance(flow, dict) and register_value in flow:
            flow[register_value] = register_number

    return flow_params<|return|>

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    if not isinstance(arg, str):
        raise TypeError(f"arg must be a string, got {type(arg).__name__}")
    return value.replace('.', arg)<|return|>

def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class type, got {type(cls).__name__}")
    seen = set()
    stack = [cls]
    while stack:
        current = stack.pop()
        try:
            subcls = current.__subclasses__()
        except Exception as exc:
            # If __subclasses__ fails, skip this branch
            continue
        for sub in subcls:
            if sub not in seen:
                seen.add(sub)
                stack.append(sub)
    return seen<|return|>

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic validation of alphabet
    if not alphabet:
        raise ValueError("alphabet must contain at least one element")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet contains duplicate elements")
    if any(len(a) != 1 for a in alphabet):
        raise ValueError("alphabet elements must be single characters")

    base = len(alphabet)
    if base == 1:
        # Only one digit possible; the string must consist of that digit only
        if all(ch == alphabet[0] for ch in string):
            return len(string)  # e.g., '111' in base-1 is 3
        else:
            raise ValueError("string contains characters not in alphabet")

    # Build mapping from character to its numeric value
    char_to_value = {ch: idx for idx, ch in enumerate(alphabet)}

    # Convert string to integer
    result = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"character '{ch}' not found in alphabet")
        result = result * base + char_to_value[ch]

    return result<|return|>

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    if not url:
        raise ValueError("URL must not be empty")
    if not isinstance(destination_path, Path):
        raise TypeError("destination_path must be a pathlib.Path instance")

    # Ensure destination directory exists and is empty
    if destination_path.exists():
        if not destination_path.is_dir():
            raise OSError(f"Destination path {destination_path} exists and is not a directory")
        # Check if directory is empty
        if any(destination_path.iterdir()):
            raise OSError(f"Destination directory {destination_path} is not empty")
    else:
        try:
            destination_path.mkdir(parents=True, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create destination directory {destination_path}") from exc

    # Download the archive to a temporary file
    temp_fd = None
    temp_path = None
    try:
        temp_fd, temp_path = tempfile.mkstemp(suffix=".tar.gz")
        with os.fdopen(temp_fd, "wb") as tmp_file:
            try:
                with requests.get(url, stream=True, timeout=30) as resp:
                    resp.raise_for_status()
                    for chunk in resp.iter_content(chunk_size=8192):
                        if chunk:
                            tmp_file.write(chunk)
            except requests.RequestException as exc:
                raise RuntimeError(f"Failed to download archive from {url}") from exc
        # Extract the archive
        try:
            with tarfile.open(temp_path, "r:gz") as tar:
                tar.extractall(path=destination_path)
        except (tarfile.TarError, OSError) as exc:
            raise RuntimeError(f"Failed to extract archive to {destination_path}") from exc
    finally:
        # Clean up temporary file
        if temp_path and os.path.exists(temp_path):
            try:
                os.remove(temp_path)
            except OSError:
                pass

    return destination_path<|return|>

def unquote(name):
    """Remove quote from the given name."""
    try:
        if not isinstance(name, str):
            return name
        # Remove leading and trailing single or double quotes
        return re.sub(r'^["\']|["\']$', '', name)
    except Exception:
        return name<|return|>

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected str, got {type(s).__name__}")
    if platform == 'this':
        import sys
        platform = 0 if sys.platform == 'win32' else 1
    if platform == 1:
        # POSIX: simple regex that respects single and double quotes
        pattern = r'''(?:"([^"]*)"|'([^']*)'|(\S+))'''
        parts = []
        for m in re.finditer(pattern, s):
            part = m.group(1) or m.group(2) or m.group(3)
            parts.append(part)
        return parts
    elif platform == 0:
        # Windows: double quotes, backslashes escape
        pattern = r'''(?:"((?:[^"\\]|\\.)*)"|(\S+))'''
        parts = []
        for m in re.finditer(pattern, s):
            part = m.group(1) or m.group(2)
            if part is not None:
                # Unescape backslashes followed by any character
                part = re.sub(r'\\(.)', r'\1', part)
            parts.append(part)
        return parts
    else:
        raise ValueError(f"Unsupported platform value: {platform}")<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for family, _, _, _, sockaddr in infos:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0].split("%")[0]  # strip zone index if present
            if ip == "::1":
                return True
    return False<|return|>

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Git Bash sets MSYSTEM to MINGW32 or MINGW64
        if os.environ.get('MSYSTEM', '').startswith('MINGW'):
            return True
        # Some setups set OSTYPE to msys
        if os.environ.get('OSTYPE', '').startswith('msys'):
            return True
    except Exception:
        pass
    return False<|return|>

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    if not config_filename:
        raise ValueError("config_filename must be a non-empty string")
    if rendered_config is None:
        raise ValueError("rendered_config must not be None")

    # If the file exists and we are not allowed to overwrite, abort
    if not overwrite and os.path.isfile(config_filename):
        return

    # Ensure the target directory exists
    dir_name = os.path.dirname(os.path.abspath(config_filename))
    try:
        os.makedirs(dir_name, exist_ok=True)
    except OSError as exc:
        # If the directory still does not exist, re-raise
        if not os.path.isdir(dir_name):
            raise

    # Write the rendered configuration to the file
    try:
        with open(config_filename, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
        # Set the file permissions
        os.chmod(config_filename, mode)
    except OSError as exc:
        # Clean up partially written file if an error occurs
        if os.path.exists(config_filename):
            try:
                os.remove(config_filename)
            except OSError:
                pass
        raise exc
<|return|>

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    # Return None if no pattern is provided
    if pattern is None:
        return None

    # If pattern is a string, optionally strip whitespace and compile it
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)

    # If pattern is already a compiled regex object, return it unchanged
    # Python 3.7+ uses re.Pattern, older versions use re._pattern_type
    if hasattr(re, "Pattern") and isinstance(pattern, re.Pattern):
        return pattern
    if hasattr(re, "_pattern_type") and isinstance(pattern, re._pattern_type):
        return pattern

    # If we reach here, the input type is unsupported
    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")<|return|>

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    if isinstance(target, ipaddress.IPv4Address):
        return True
    try:
        addr = ipaddress.ip_address(target)
        return isinstance(addr, ipaddress.IPv4Address)
    except (ValueError, TypeError):
