def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    import sys
    try:
        # Use safe_dump for a safe representation
        if dumper is None:
            yaml_str = yaml.safe_dump(
                obj,
                default_flow_style=False,
                allow_unicode=True,
            )
        else:
            yaml_str = yaml.safe_dump(
                obj,
                Dumper=dumper,
                default_flow_style=False,
                allow_unicode=True,
            )
        # In Python 2, yaml.safe_dump returns a byte string; convert to unicode
        if sys.version_info[0] < 3:
            if isinstance(yaml_str, bytes):
                yaml_str = yaml_str.decode("utf-8")
        return yaml_str
    except Exception as exc:
        raise ValueError(f"Failed to dump object to YAML string: {exc}") from exc<|return|>

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple or int
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Normalize shape to a tuple of integers
    if isinstance(shape, int):
        shape = (shape,)
    if not isinstance(shape, (tuple, list)):
        raise TypeError("shape must be an int, tuple, or list of integers")
    try:
        shape = tuple(int(s) for s in shape)
    except Exception as exc:
        raise TypeError("shape must contain integers") from exc
    if any(s < 0 for s in shape):
        raise ValueError("shape dimensions must be non-negative")

    # Validate and convert dtype
    try:
        dtype = np.dtype(dtype)
    except Exception as exc:
        raise TypeError("dtype must be a valid numpy dtype") from exc

    # Create the array
    try:
        arr = np.empty(shape, dtype=dtype)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array: {exc}") from exc

    return arr<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import logging
    configs = {}
    errors = []

    def _resolve_env_vars(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, dict):
            return {k: _resolve_env_vars(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_resolve_env_vars(v) for v in value]
        return value

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
            # Determine parser by extension
            if fname.lower().endswith('.toml'):
                try:
                    import toml
                except ImportError:
                    raise ImportError('toml module is required to parse .toml files')
                cfg = toml.loads(raw)
            elif fname.lower().endswith(('.yaml', '.yml')):
                try:
                    import yaml
                except ImportError:
                    raise ImportError('yaml module is required to parse .yaml files')
                cfg = yaml.safe_load(raw)
            elif fname.lower().endswith('.json'):
                import json
                cfg = json.loads(raw)
            else:
                # Try yaml first, then json
                try:
                    import yaml
                    cfg = yaml.safe_load(raw)
                except Exception:
                    import json
                    cfg = json.loads(raw)
            if not isinstance(cfg, dict):
                raise ValueError('Configuration is not a dictionary')
            if overrides:
                cfg.update(overrides)
            if resolve_env:
                cfg = _resolve_env_vars(cfg)
            configs[fname] = cfg
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f'Error loading {fname}: {e}',
                args=None,
                exc_info=None
            )
            errors.append(record)
    return configs, errors<|return|>

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    try:
        # Handle Python 2/3 string types
        try:
            unicode_type
        except NameError:
            unicode_type = str
        if isinstance(obj, unicode_type) and not isinstance(obj, bytes):
            return obj.encode('utf-8')
        elif isinstance(obj, bytes):
            return obj
        else:
            return obj
    except Exception as e:
        raise ValueError(f"Could not convert object to bytes: {e}") from e<|return|>

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Retrieve the mapping of handlers from the class.  The class is
    # expected to define a class attribute `_protocol_handlers` which
    # is a dict mapping version tuples to handler classes.  If that
    # attribute is missing or not a dict, treat it as an empty mapping.
    handlers = getattr(cls, "_protocol_handlers", {})
    if not isinstance(handlers, dict):
        handlers = {}

    if protocol_version is None:
        # Return a copy of all handlers
        return dict(handlers)

    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple or None")

    # Return only the requested version if it exists
    if protocol_version in handlers:
        return {protocol_version: handlers[protocol_version]}
    return {}<|return|>

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise TypeError("values must be an iterable of strings, got None")
    if isinstance(values, str):
        raise TypeError("values must be an iterable of strings, not a single string")
    bookmarks = []
    for v in values:
        if not isinstance(v, str):
            raise TypeError(f"Bookmark value must be a string, got {type(v).__name__}")
        try:
            # Prefer a dedicated raw-value constructor if available
            bookmark = Bookmark.from_raw_value(v)
        except AttributeError:
            # Fallback to the default constructor
            bookmark = Bookmark(v)
        except Exception as exc:
            raise ValueError(f"Failed to parse bookmark from raw value: {v!r}") from exc
        bookmarks.append(bookmark)
    return cls(bookmarks)<|return|>

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised."""
    try:
        return super().pop(key)
    except KeyError:
        if default is not __marker:
            return default
        raise

<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('dict is empty')
    freq_map = getattr(self, '_freq', None)
    if freq_map is None:
        return super().popitem()
    try:
        min_freq = min(freq_map.values())
    except Exception:
        raise KeyError('dict is empty')
    for key, freq in freq_map.items():
        if freq == min_freq:
            value = self.pop(key)
            del freq_map[key]
            return key, value
    return super().popitem()
<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        return super().popitem()
    except KeyError:
        raise KeyError('dict is empty')<|return|>

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    try:
        import random
        if not self:
            raise KeyError('dict is empty')
        key = random.choice(list(self.keys()))
        value = self.pop(key)
        return (key, value)
    except KeyError:
        raise
    except Exception as e:
        raise RuntimeError(f"Unexpected error during popitem: {e}") from e<|return|>

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    # The regex matches an 'in' keyword followed by optional whitespace and a
    # parenthesized list of comma‑separated values.  The values themselves are
    # captured as a single group so that callers can split them later.
    pattern = r'\b(in)\s*\(([^)]*)\)'
    try:
        return re.compile(pattern, flags=re.IGNORECASE)
    except re.error as exc:
        raise ValueError(f"Failed to compile in‑style regex: {exc}") from exc<|return|>

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    def _convert(params):
        # Accept dict, list/tuple, or None
        if params is None:
            return {}
        if isinstance(params, dict):
            return params
        if isinstance(params, (list, tuple)):
            return {f"arg{i}": v for i, v in enumerate(params)}
        raise TypeError("Parameters must be a dict, list, tuple, or None")
    return _converting._Converter(_convert)<|return|>

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        body = getattr(request, 'body', None)
        if body is None:
            return False
        if isinstance(body, bytes):
            body_str = body.decode('utf-8', errors='ignore')
        else:
            body_str = str(body)
        try:
            import json
            data = json.loads(body_str)
            if isinstance(data, dict) and "encrypted_magic_envelope" in data:
                return True
        except Exception:
            pass
        try:
            import xml.etree.ElementTree as ET
            root = ET.fromstring(body_str)
            if root.tag == "magic_env":
                return True
        except Exception:
            pass
    except Exception:
        pass
    return False<|return|>

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    if request is None:
        return False

    # Attempt to get the request path
    path = None
    try:
        if hasattr(request, "path"):
            path = request.path
        elif isinstance(request, dict) and "path" in request:
            path = request["path"]
    except Exception:
        path = None

    if isinstance(path, str) and path.startswith("/_matrix"):
        return True

    # Attempt to get headers in a variety of common formats
    headers = None
    try:
        if hasattr(request, "headers"):
            headers = request.headers
        elif hasattr(request, "META"):
            # Django style META dictionary
            headers = {k[5:]: v for k, v in request.META.items() if k.startswith("HTTP_")}
        elif isinstance(request, dict):
            headers = request.get("headers") or request.get("META")
    except Exception:
        headers = None

    if isinstance(headers, dict):
        # Normalise header keys to lower case
        hdrs = {k.lower(): v for k, v in headers.items() if isinstance(k, str)}
        # Common Matrix indicators
        if "x-requested-with" in hdrs and "matrix" in hdrs["x-requested-with"].lower():
            return True
        if "content-type" in hdrs and "application/json" in hdrs["content-type"].lower():
            return True
        if "x-matrix" in hdrs:
            return True

    return False<|return|>

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if dt is None:
        raise ValueError("dt cannot be None")
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime instance")
    # Convert to UTC if timezone-aware, otherwise assume UTC
    if dt.tzinfo is None:
        dt_utc = dt
    else:
        dt_utc = dt.astimezone(datetime.timezone.utc)
    # Format as ISO 8601 with trailing 'Z' to indicate UTC
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")<|return|>

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    # Use a simple regex to find URLs. Import re lazily to avoid top-level imports.
    try:
        re = __import__('re')
    except Exception as exc:
        raise RuntimeError("Failed to import regex module") from exc
    url_pattern = re.compile(r'(https?://[^\s]+)')
    def replace_url(match):
        url = match.group(0)
        # Escape double quotes in URL if any (unlikely but safe)
        escaped_url = url.replace('"', '&quot;')
        return f'<a href="{escaped_url}" target="_blank" rel="noopener noreferrer">{escaped_url}</a>'
    try:
        return url_pattern.sub(replace_url, text)
    except Exception as exc:
        # If substitution fails, return original text to avoid breaking the caller
        return text<|return|>

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        parsed = urlparse(url)
        if parsed.scheme not in ("http", "https"):
            return None
        req = Request(url, method="HEAD")
        with urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                return None
            return resp.headers.get("Content-Type")
    except Exception:
        return None<|return|>

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("'tag' must be a string")
    tag = tag.strip()
    if not tag:
        return False
    # Tag must be 1-30 characters, start with a letter, and contain only letters, digits, hyphens, or underscores
    if len(tag) > 30:
        return False
    import re
    pattern = re.compile(r'^[A-Za-z][A-Za-z0-9_-]*$')
    return bool(pattern.match(tag))<|return|>

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("node must be an ElementTree element") from exc

    result = {}
    for child in children:
        tag = child.tag
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate input types
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if document_path is not None and not isinstance(document_path, str):
        raise TypeError("document_path must be a string if provided")

    # Default path if none supplied
    if document_path is None:
        document_path = "/.well-known/nodeinfo"
    else:
        # Ensure the path starts with a slash
        if not document_path.startswith("/"):
            document_path = "/" + document_path
        # Remove any trailing slash to avoid double slashes when joining
        document_path = document_path.rstrip("/")

    # Construct the full href
    href = url.rstrip("/") + document_path

    # Build the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None

    result = {}

    # Try JSON format first
    try:
        json_mod = __import__("json")
        data = json_mod.loads(document)
        links = data.get("links", [])
        for link in links:
            rel = link.get("rel", "").lower()
            href = link.get("href")
            if not href:
                continue
            if "hcard" in rel:
                result["hcard_url"] = href
            elif "avatar" in rel:
                result["avatar_url"] = href
            elif "self" in rel:
                result["self_url"] = href
        if result:
            return result
    except Exception:
        pass

    # Try XRD (XML) format
    try:
        ET = __import__("xml.etree.ElementTree")
        root = ET.fromstring(document)
        # Iterate over all elements that might be Link elements
        for elem in root.iter():
            tag = elem.tag
            # Handle namespace if present
            if tag.endswith("Link"):
                rel = elem.attrib.get("rel", "").lower()
                href = elem.attrib.get("href")
                if not href:
                    continue
                if "hcard" in rel:
                    result["hcard_url"] = href
                elif "avatar" in rel:
                    result["avatar_url"] = href
                elif "self" in rel:
                    result["self_url"] = href
        if result:
            return result
    except Exception:
        pass

    return None<|return|>

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host,
        path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    lrdd_link = hostmeta.find_link(rels="lrdd")
    if not lrdd_link:
        return None
    url = lrdd_link.template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        # Normalize settings_dirs to a list
        if settings_dirs is None:
            return []
        if isinstance(settings_dirs, (str, bytes)):
            dirs = [settings_dirs]
        else:
            try:
                dirs = list(settings_dirs)
            except TypeError:
                # Not iterable, treat as single directory
                dirs = [settings_dirs]

        matched_files = []

        for directory in dirs:
            try:
                for fname in os.listdir(directory):
                    full_path = os.path.join(directory, fname)

                    # If spec_option is None or empty, accept all files
                    if not spec_option:
                        matched_files.append(full_path)
                        continue

                    # If spec_option is a list/tuple of patterns
                    if isinstance(spec_option, (list, tuple)):
                        for pattern in spec_option:
                            if isinstance(pattern, str):
                                # Use fnmatch for wildcard patterns
                                try:
                                    if fnmatch.fnmatch(fname, pattern):
                                        matched_files.append(full_path)
                                        break
                                except Exception:
                                    continue
                            else:
                                # Unsupported pattern type, skip
                                continue
                        continue

                    # If spec_option is a string
                    if isinstance(spec_option, str):
                        # Treat as wildcard pattern if it contains *, ?, or []
                        if any(c in spec_option for c in ('*', '?', '[')):
                            try:
                                if fnmatch.fnmatch(fname, spec_option):
                                    matched_files.append(full_path)
                            except Exception:
                                continue
                        else:
                            # Treat as file extension
                            if fname.endswith(spec_option):
                                matched_files.append(full_path)
                        continue

                    # If spec_option is a callable, use it to filter
                    if callable(spec_option):
                        try:
                            if spec_option(fname):
                                matched_files.append(full_path)
                        except Exception:
                            continue

                    # Unsupported spec_option type: skip
            except OSError:
                # Skip directories that cannot be accessed
                continue

        return sorted(matched_files)
    except Exception:
        # In case of unexpected errors, return an empty list
        return []<|return|>

