@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Ensure content is provided
        if spec_content is None:
            raise IRValidatorException("spec_content must be provided")

        # Accept bytes or string
        if isinstance(spec_content, bytes):
            try:
                spec_content = spec_content.decode('utf-8')
            except Exception as e:
                raise IRValidatorException(f"Unable to decode spec_content: {e}")

        if not isinstance(spec_content, str):
            raise IRValidatorException("spec_content must be a string or bytes")

        # Parse YAML
        try:
            data = yaml.safe_load(spec_content)
        except Exception as e:
            raise IRValidatorException(f"Error parsing YAML content: {e}")

        if data is None:
            raise IRValidatorException("YAML content is empty or invalid")

        # Determine required fields
        required_fields = getattr(cls, "REQUIRED_FIELDS", None)
        if required_fields is None:
            raise IRValidatorException("No REQUIRED_FIELDS defined for validation")

        # Validate presence of required fields
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

        return data<|return|>

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        # Ensure a file path was provided
        if yaml_file is None:
            raise IRValidatorException("yaml_file argument must be supplied")

        # Convert to Path if necessary
        try:
            from pathlib import Path
            yaml_path = Path(yaml_file)
        except Exception as e:
            raise IRValidatorException(f"Invalid file path: {e}")

        # Check that the file exists
        if not yaml_path.is_file():
            raise IRValidatorException(f"File not found: {yaml_path}")

        # Load the YAML content
        try:
            with yaml_path.open("r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except Exception as e:
            raise IRValidatorException(f"Error loading YAML file {yaml_path}: {e}")

        # If the file is empty or not a mapping, raise an error
        if not isinstance(data, dict):
            raise IRValidatorException(f"YAML file {yaml_path} does not contain a mapping")

        # Validate required fields if the class defines them
        required_fields = getattr(cls, "REQUIRED_FIELDS", None)
        if required_fields:
            missing = [field for field in required_fields if field not in data]
            if missing:
                raise IRValidatorException(
                    f"Missing required fields in {yaml_path}: {', '.join(missing)}"
                )

        return data<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    def _resolve(d):
        for key, val in list(d.items()):
            if isinstance(val, dict) and 'include' in val:
                inc = val['include']
                if isinstance(inc, str):
                    try:
                        inc_dict = self._load_spec(inc)
                    except Exception as e:
                        raise FileNotFoundError(f"Failed to load include file '{inc}': {e}") from e
                elif isinstance(inc, list):
                    inc_dict = {}
                    for inc_file in inc:
                        try:
                            inc_dict.update(self._load_spec(inc_file))
                        except Exception as e:
                            raise FileNotFoundError(f"Failed to load include file '{inc_file}': {e}") from e
                else:
                    raise ValueError(f"Invalid include directive for key '{key}': {inc!r}")
                d[key] = inc_dict
                _resolve(d[key])
            elif isinstance(val, dict):
                _resolve(val)
    _resolve(parser_dict)
    return parser_dict<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    spec = getattr(self, 'spec', None)
    if spec is None:
        return defaults

    # Sentinel for missing values
    _MISSING = object()

    for arg in getattr(self, 'args', []):
        # Skip objects that don't have a name attribute
        if not hasattr(arg, 'name'):
            continue

        # Attempt to get the value from the spec
        if isinstance(spec, dict):
            val = spec.get(arg.name, _MISSING)
        else:
            val = getattr(spec, arg.name, _MISSING)

        if val is not _MISSING:
            defaults[arg.name] = val
        else:
            # Fallback to the argument's own default if it exists
            if hasattr(arg, 'default') and arg.default is not None:
                defaults[arg.name] = arg.default

        # If the argument is a nested dictionary option, merge its defaults
        if hasattr(arg, 'scheme') and getattr(arg, 'scheme', None):
            try:
                nested = arg.scheme.get_spec_defaults()
                if nested:
                    defaults[arg.name] = nested
            except Exception:
                # Ignore errors from nested resolution to avoid breaking the whole process
                pass

    return defaults<|return|>

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Validate input types
    if not isinstance(cli_args, dict):
        raise TypeError("cli_args must be a dict")
    if not isinstance(answer_file_args, dict):
        raise TypeError("answer_file_args must be a dict")

    # Retrieve the mapping of deprecated arguments if available
    deprecated_map = getattr(self, "deprecated_args", {})
    if not isinstance(deprecated_map, dict):
        raise TypeError("self.deprecated_args must be a dict mapping old to new names")

    # Collect deprecated arguments found in both sources
    found_deprecated = {}
    for arg_name in cli_args:
        if arg_name in deprecated_map:
            found_deprecated[arg_name] = deprecated_map[arg_name]
    for arg_name in answer_file_args:
        if arg_name in deprecated_map:
            found_deprecated[arg_name] = deprecated_map[arg_name]

    # Print warnings for each deprecated argument
    for old_name, new_name in found_deprecated.items():
        print(f"WARNING: Argument '{old_name}' is deprecated. "
              f"Use '{new_name}' instead.")
    # No return value needed; the method is used for side‑effects only.<|return|>

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if command_name is None:
        raise TypeError("command_name must not be None")
    if not isinstance(command_name, str):
        raise TypeError(f"command_name must be a string, got {type(command_name).__name__}")

    # Locate the mapping that holds command options
    options_map = getattr(self, "command_options", None)
    if options_map is None:
        options_map = getattr(self, "_command_options", None)
    if options_map is None:
        raise AttributeError(
            "The object does not have a 'command_options' or '_command_options' attribute"
        )

    # Retrieve the options for the requested command
    try:
        options = options_map[command_name]
    except KeyError:
        raise ValueError(f"Unknown command name: {command_name!r}")

    # Ensure the returned value is a list
    if not isinstance(options, list):
        raise TypeError(
            f"Options for command {command_name!r} must be a list, got {type(options).__name__}"
        )

    return options<|return|>

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate inputs
    if command_name is None or argument_name is None:
        raise ValueError("Both command_name and argument_name must be provided")
    if not isinstance(command_name, str) or not isinstance(argument_name, str):
        raise TypeError("command_name and argument_name must be strings")

    # Attempt to retrieve the command definition
    try:
        command = self.commands[command_name]
    except (AttributeError, KeyError, TypeError):
        raise KeyError(f"Command '{command_name}' not found in available commands")

    # Determine where the options are stored
    options_container = None
    if hasattr(command, "options") and isinstance(command.options, (dict, list)):
        options_container = command.options
    elif isinstance(command, dict):
        options_container = command
    else:
        raise AttributeError(f"Command '{command_name}' does not expose an options container")

    # Retrieve the option specification
    try:
        if isinstance(options_container, dict):
            spec = options_container[argument_name]
        else:  # list or other iterable of option specs
            # Assume each item has a 'name' attribute or key
            for opt in options_container:
                name = getattr(opt, "name", None) or opt.get("name") if isinstance(opt, dict) else None
                if name == argument_name:
                    spec = opt
                    break
            else:
                raise KeyError
    except KeyError:
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")

    return spec
<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # If the class does not define required arguments, nothing to validate
    if not hasattr(self, 'required_args'):
        return

    # Ensure we have a mapping of arguments
    if args is None:
        raise InvalidArgumentError('Arguments cannot be None.')
    if not isinstance(args, dict):
        raise InvalidArgumentError('Arguments must be a mapping (dict).')

    # Identify any missing required arguments
    missing = [name for name in self.required_args
               if name not in args or args[name] is None]

    if missing:
        raise InvalidArgumentError(
            'Missing required arguments: {}'.format(', '.join(missing))
        )<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Validate inputs
    if options_spec is None:
        return []
    if not isinstance(options_spec, (list, tuple)):
        raise TypeError("options_spec must be a list or tuple of option specs")
    # Ensure args is a mapping
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception as exc:
            raise TypeError("args must be a mapping or convertible to dict") from exc

    required = []
    for opt in options_spec:
        # Support dict or object with attributes
        if isinstance(opt, dict):
            name = opt.get("name")
            cond = opt.get("required_when")
        else:
            name = getattr(opt, "name", None)
            cond = getattr(opt, "required_when", None)

        if not name:
            continue
        if cond is None:
            continue

        try:
            # If condition is callable, call it with command_name and args
            if callable(cond):
                if cond(command_name, args):
                    required.append(name)
            else:
                # Treat condition as a string expression
                # Provide args and command_name in local namespace
                local_ns = dict(args)
                local_ns["command_name"] = command_name
                if eval(cond, {}, local_ns):
                    required.append(name)
        except Exception:
            # If evaluation fails, ignore this option
            continue

    return required<|return|>

