def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument values")

    # Retrieve argument definitions from the parsed configuration
    arg_defs = getattr(self, "parsed_yaml", {}).get("args", {})
    if not isinstance(arg_defs, dict):
        # If the structure is unexpected, nothing to validate
        return

    for arg_name, arg_attrs in arg_defs.items():
        # Skip non-dict attribute definitions
        if not isinstance(arg_attrs, dict):
            continue

        # Only validate arguments that declare a set of allowed choices
        if "choices" not in arg_attrs:
            continue

        choices = arg_attrs["choices"]
        # Ensure the choices are an iterable of allowed values
        if not isinstance(choices, (list, tuple, set)):
            continue

        # Skip validation if the argument was not supplied
        if arg_name not in args:
            continue

        value = args[arg_name]
        # If the supplied value is None, we consider it acceptable (e.g., optional)
        if value is None:
            continue

        if value not in choices:
            raise ValueError(
                f"Invalid value for argument '{arg_name}': {value!r}. "
                f"Expected one of {choices!r}"
            )<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is an iterable
    if args is None:
        raise TypeError("args must not be None")
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError("args must be an iterable")

    for idx, arg in enumerate(iterator):
        try:
            # Determine value, min, and max from various possible structures
            if isinstance(arg, dict):
                value = arg.get("value")
                min_ = arg.get("min")
                max_ = arg.get("max")
            elif isinstance(arg, (list, tuple)) and len(arg) == 3:
                value, min_, max_ = arg
            else:
                # Try to access attributes
                value = getattr(arg, "value", None)
                min_ = getattr(arg, "min", None)
                max_ = getattr(arg, "max", None)

            # Validate that we have all three components
            if value is None or min_ is None or max_ is None:
                raise TypeError(
                    f"Argument at index {idx} is missing required 'value', 'min', or 'max' components"
                )

            # Perform the bounds check
            if not (min_ <= value <= max_):
                raise ValueError(
                    f"Argument at index {idx} with value {value} is out of bounds [{min_}, {max_}]"
                )
        except Exception as exc:
            # Re-raise with context
            raise type(exc)(f"Error validating argument at index {idx}: {exc}") from exc

    return args<|return|>

