        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if vars_dict is None:
            raise ValueError("vars_dict cannot be None")
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")

        if not extra_vars:
            return vars_dict

        # If extra_vars is a single dictionary, merge it directly
        if isinstance(extra_vars, dict):
            for key, value in extra_vars.items():
                vars_dict[key] = value
            return vars_dict

        # If extra_vars is a list, iterate over its items
        if isinstance(extra_vars, list):
            for item in extra_vars:
                if isinstance(item, dict):
                    for key, value in item.items():
                        vars_dict[key] = value
                elif isinstance(item, (list, tuple)) and len(item) == 2:
                    key, value = item
                    vars_dict[key] = value
                else:
                    # Unsupported item type; skip or raise an error
                    continue
            return vars_dict

        # Unsupported type for extra_vars
        raise TypeError("extra_vars must be a dict or a list of dicts/tuples")<|return|>

