def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    spec_path_json = os.path.join(plugin_dir, 'plugin.json')
    spec_path_yaml = os.path.join(plugin_dir, 'plugin.yaml')
    spec_path_yml = os.path.join(plugin_dir, 'plugin.yml')

    spec_file = None
    if os.path.isfile(spec_path_json):
        spec_file = spec_path_json
    elif os.path.isfile(spec_path_yaml):
        spec_file = spec_path_yaml
    elif os.path.isfile(spec_path_yml):
        spec_file = spec_path_yml

    if not spec_file:
        return {}

    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            if spec_file.endswith('.json'):
                data = json.load(f)
            else:
                # Attempt to load YAML if available
                try:
                    import yaml
                    data = yaml.safe_load(f)
                except Exception:
                    # Fallback: treat as plain text
                    return {}
    except Exception:
        return {}

    if not isinstance(data, dict):
        return {}

    return _flatten(data)<|return|>

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("path and root must be strings")
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    if norm_root == '':
        raise ValueError("root cannot be empty")
    if norm_path == norm_root:
        return ''
    if norm_path.startswith(norm_root + os.sep):
        return norm_path[len(norm_root) + 1:]
    else:
        raise ValueError(f"Path '{path}' does not start with root '{root}'")<|return|>
